### 🧠 Step 3: Networking & Logic (ViewModel)

**`TodoViewModel.kt`**
```kotlin
package com.example.todoapp.logic

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.todoapp.data.room.TaskDao
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import java.text.SimpleDateFormat
import java.util.*

class TodoViewModel(
    private val taskDao: TaskDao
) : ViewModel() {

    private val _tasks: MutableStateFlow<List<Task>> = MutableStateFlow(listOf())
    val tasks: StateFlow<List<Task>> = _tasks.asStateFlow()

    private val tasksMap = mutableMapOf<String, Task>()

    fun loadTasks() {
        // Load all tasks from DB
        taskDao.getTaskList().observe(viewModel.scope) { 
            _tasks.value = it                
             tasksMap.keys.forEach { key -> tasksMap[key] = it.toTask(key) }
        }
    }

    fun addTask(title: String, reminder: String, isCompleted: Boolean = false) {
        viewModelScope.launch {
            val today = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
            val reminderDate = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())

            // Parse or trigger reminder
            val task = Task(
                id = UUID.randomUUID().toString(),
                title = title,
                isCompleted = isCompleted,
                reminderDate = reminderDate
            )
            taskDao.insert(task)
            loadTasks()
        }
    }

    fun toggleTask(id: String) {
        viewModelScope.launch {
            val task = tasksMap[id]
            if (task != null) {
                taskDao.update(task.copy(isCompleted = !task.isCompleted))
            }
        }
    }

    fun deleteTask(id: String) {
        viewModelScope.launch {
            taskDao.delete(
                Task(
                    id = id,
                    title = "",
                    isCompleted = false,
                    reminderDate = ""
                )
            )
        }
    }

    fun deleteAllTasks() {
        viewModelScope.launch {
            taskDao.delete(taskDao.getTaskList())
        }
    }

    // Helper to load tasks correctly
    private fun Task.toTask(id: String): Task {
        return if (title.isNotEmpty()) this else Task(id = "", title = "", isCompleted = false, reminderDate = "")
    }
}
```

